// #region typings

export type FilterFieldSuggestions = FilterFieldSuggestionProps[];

export type FilterFieldSuggestionsCallback = (state?: {
  /** The type of suggestions that should be shown for the current cursor position. */
  suggestionType: 'key' | 'value' | 'comparisonOperator' | 'none';
  /** The token at the current cursor position. */
  currentToken: FilterFieldLeafNode;
  /** The current value of the filter field. */
  value: string;
  /** Array of suggestions to display for the current cursor position (logical / comparison operators). */
  autoSuggestions: FilterFieldSuggestions;
  /** Syntax tree of the current value. */
  syntaxTree: FilterFieldTree;
  /** The current position of the cursor. */
  cursorPosition: number;
  /** The filter statement at the current cursor position. */
  currentStatement?: FilterFieldStatementNode;
}) => void;

/**
 * Accepted properties for FilterField.
 */
export type FilterFieldProps = WithChildren &
  StylingProps &
  DataTestId &
  // TODO The filterfield doesn't support readonly yet.
  Omit<
    FormControlProps<string, (value: string, tree: FilterFieldTree) => void>,
    'readOnly'
  > & {
    /**
     * Placeholder text displayed when the filter field is empty.
     * @defaultValue 'Type to filter'
     */
    placeholder?: string;
    /**
     * Whether the automatically determined suggestions (logical / comparison operators) should be shown.
     * If set to true, the suggestions will automatically be added to the suggestions overlay.
     * @defaultValue false
     */
    autoSuggestions?: boolean;
    /**
     * Callback triggered when the suggestions may need to be updated.
     * @defaultValue undefined
     */
    onSuggest?: FilterFieldSuggestionsCallback;
    /**
     * Callback triggered when the user submits the currently entered filter for filtering.
     * @defaultValue undefined
     */
    onFilter?: (filterState: {
      value: string;
      syntaxTree: FilterFieldTree;
      isValid: boolean;
    }) => void;
  };
// #endregion typings

const placeholderCompartment = new Compartment();
const suggestionsCompartment = new Compartment();
const ariaAttributesCompartment = new Compartment();

const stringAnnotation = Annotation.define<string>();

/** List of keys that are handled separately and should not trigger the default behavior. */
const overrideKeys = ['ArrowUp', 'ArrowDown', 'Enter', 'Mod-Enter'];

const _FilterField = forwardRef<HTMLElement, FilterFieldProps>(
  (props, forwardedRef) => {
    const {
      children,
      name,
      value,
      defaultValue,
      required: propRequired = false,
      disabled: propDisabled = false,
      placeholder: placeholderProp,
      id: propId,
      autoSuggestions = false,
      controlState,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      onChange,
      onSuggest,
      onFilter,
    }: FilterFieldProps = props;

    const uniqueId = _useId({ prefix: 'filter-field' });
    const ariaLabelingProps = _useAriaLabelingProps(props);

    const intl = useIntl();

    const numberParser = _useParseNumber();
    // Ref to use in the codemirror extensions where needed.
    const numberParserRef = useRef(numberParser);
    useEffect(() => {
      numberParserRef.current = numberParser;
    }, [numberParser]);

    // Values from previous render-cycle to trigger updates while rendering.
    // This way, we can avoid using effects, which would trigger another render.
    const [prevValue, setPrevValue] = useState(value);
    // Prev value ref to use in everything codemirror related.
    const prevValueRef = useRef(value);
    useEffect(() => {
      prevValueRef.current = prevValue;
    }, [prevValue]);

    const [prevPropDisabled, setPrevPropDisabled] = useState(propDisabled);
    const [prevPropRequired, setPrevPropRequired] = useState(propRequired);
    const [prevPropId, setPrevPropId] = useState(propId);

    const [prevPlaceholderProp, setPrevPlaceholderProp] =
      useState(placeholderProp);
    const [prevOnSuggest, setPrevOnSuggest] = useState(() => onSuggest);
    const [prevChildren, setPrevChildren] = useState(children);
    const [
      prevShowLogicalOperatorSuggestions,
      setPrevShowLogicalOperatorSuggestions,
    ] = useState(false);
    const [
      prevShowComparisonOperatorSuggestions,
      setPrevShowComparisonOperatorSuggestions,
    ] = useState(false);
    const [prevShowValueSuggestions, setPrevShowValueSuggestions] =
      useState(false);

    const isControlled = value !== undefined;

    const placeholder = intl.formatMessage({
      defaultMessage: 'Type to filter',
      id: 'GhC5F6ZRFGDVs41W',
      description: 'Default placeholder text shown in the filter field.',
    });
    const defaultAriaLabel = intl.formatMessage({
      defaultMessage: 'Filter field',
      id: 'swS1rIU8VQep1PDq',
      description: 'Default aria label for the filter field',
    });

    // Suggestions overlay setup.
    const suggestionsOverlayRef = useRef<HTMLDivElement | null>(null);
    const {
      targetRef,
      overlayRef: _overlayRef,
      overlayState,
      overlayProps: _overlayProps,
    } = useOverlayWithTrigger({
      placement: 'bottom-start',
      placementFallbacks: ['top-start'],
      widthStrategy: 'trigger',
      offset: 4,
    });
    const [prevOpen, setPrevOpen] = useState(overlayState.isOpen);
    const prevOpenRef = useRef(prevOpen);
    useEffect(() => {
      prevOpenRef.current = prevOpen;
    }, [prevOpen]);
    const overlayRef = useMergeRefs([suggestionsOverlayRef, _overlayRef]);
    const { style: overlayStyles } = _overlayProps;

    // Element refs.
    const containerRef = useRef<HTMLDivElement | null>(null);
    const editorViewRef = useRef<EditorView | null>(null);
    const rootRef = useMergeRefs([targetRef, forwardedRef]);
    const hiddenInputRef = useRef<HTMLInputElement | null>(null);

    // Linting.
    const filterFieldLinter = useFilterFieldLinting();
    const [hasFormControlError, hint] = _useFormControlState(controlState);
    const [hasSyntaxError, setHasSyntaxError] = useState(false);
    const {
      state: formFieldMessageState,
      dispatch: formFieldMessageContextDispatch,
    } = useFormFieldMessagesContext();
    const hasError =
      !editorViewRef.current?.hasFocus &&
      (hasSyntaxError || hasFormControlError || formFieldMessageState.hasError);

    // Form hint / error.
    const { containerProps, inputProps, hintProps } = _useInputHint({
      hint,
      hasError,
    });

    // Flag for the form validation to indicate whether the FilterField has been blurred.
    const isDirtyRef = useRef<boolean>(false);

    const {
      controlId,
      required: contextRequired,
      disabled: contextDisabled,
      dispatch: formFieldContextDispatch,
    } = _useFormFieldContext();

    const disabled = propDisabled || contextDisabled;
    const required = propRequired || contextRequired;

    // FilterField form control message ids
    const filterFieldCustomErrorRef = useRef<string>(
      _useId({ prefix: 'strato-filterfield-error' }),
    );
    const filterFieldRequiredErrorRef = useRef<string>(
      _useId({ prefix: 'strato-filterfield-error' }),
    );

    const validate = () => {
      // Handle required error
      if (valueRef.current === '' && required) {
        // Add required error.
        formFieldMessageContextDispatch({
          type: FormFieldMessagesAction.ADDMESSAGE,
          payload: {
            id: filterFieldRequiredErrorRef.current,
            validityStateKey: 'valueMissing',
            variant: 'error',
            message: (
              <Text textStyle="small" as="p">
                {_getI18nErrorMessage('valueMissing', hiddenInputRef.current)}
              </Text>
            ),
            messageType: 'formcontrol',
          },
        });
      } else if (valueRef.current !== '' && required) {
        // clean up required error
        formFieldMessageContextDispatch({
          type: FormFieldMessagesAction.REMOVEMESSAGE,
          payload: {
            id: filterFieldRequiredErrorRef.current,
            messageType: 'formcontrol',
          },
        });
      }

      // Handle internal syntax error.
      if (hasSyntaxError) {
        formFieldMessageContextDispatch({
          type: FormFieldMessagesAction.ADDMESSAGE,
          payload: {
            id: filterFieldCustomErrorRef.current,
            validityStateKey: 'customError',
            variant: 'error',
            message: intl.formatMessage({
              defaultMessage: 'Invalid syntax.',
              id: 'ut5dPv/qM9qMEW4a',
              description:
                'Error message shown when the Input in the FilterField has an invalid syntax.',
            }),
            messageType: 'formcontrol',
          },
        });
      } else {
        formFieldMessageContextDispatch({
          type: FormFieldMessagesAction.REMOVEMESSAGE,
          payload: {
            id: filterFieldCustomErrorRef.current,
            messageType: 'formcontrol',
          },
        });
      }
    };

    const onInputChange = () => {
      // only validate on change when there is an error
      if (isDirtyRef.current) {
        validate();
      }
    };

    const onInputBlur = () => {
      // always validate on blur
      isDirtyRef.current = true;
      validate();
    };

    // States for showing different types of auto suggestions.
    const [showLogicalOperatorSuggestions, setShowLogicalOperatorSuggestions] =
      useState(false);
    const [
      showComparisonOperatorSuggestions,
      setShowComparisonOperatorSuggestions,
    ] = useState(false);
    const [showValueSuggestions, setShowValueSuggestions] = useState(false);

    // The currently entered last term to use for highlighting matching parts of suggestions.
    const suggestionsContext = useRef<
      _FilterFieldSuggestionsContext | undefined
    >();

    const [focusedSuggestion, setFocusedSuggestion] = useState<
      string | undefined
    >();
    // Previously focused suggestion. Used to trigger an update of the attributes
    // compartment when rendering to avoid an additional re-render.
    const prevFocusedSuggestion = usePrevious(focusedSuggestion);

    // Suggestions callback to determine which suggestions to show.
    const _onSuggest: _FilterFieldSuggestionsCallback = useCallback(
      ([
        suggestionContext,
        showLogicalOperators,
        showComparisonOperators,
        showValueOperators,
      ]) => {
        suggestionsContext.current = suggestionContext;
        setShowComparisonOperatorSuggestions(showComparisonOperators);
        setShowLogicalOperatorSuggestions(showLogicalOperators);
        setShowValueSuggestions(showValueOperators);
      },
      [],
    );

    // FilterField state.
    const [state, dispatch] = useReducer(filterFieldReducer, {
      suggestions: new Map(),
      activeSuggestion: -1,
    });
    const [hideDeleteWhileTyping, setHideDeleteWhileTyping] = useState(false);

    /**
     * Apply the given suggested value to the document, replacing the selection
     * so that the cursor end up at the end of the inserted text.
     */
    const applySuggestion = useCallback(
      (value: string, mode: _FilterFieldSuggestionMode) => {
        if (!editorViewRef.current || !suggestionsContext.current) {
          return;
        }

        const currentDocumentLength =
          editorViewRef.current.state.doc.toString().length;
        const currentSelection = editorViewRef.current.state.selection;
        const { head } = currentSelection.main;
        const range =
          mode === 'insert'
            ? {
                from: head,
                to: head,
              }
            : {
                from: Math.min(
                  currentDocumentLength,
                  suggestionsContext.current.token.range.from,
                ),
                to: Math.min(
                  currentDocumentLength,
                  suggestionsContext.current.token.range.to,
                ),
              };

        // The applied suggestion will always override the last token.
        editorViewRef.current.dispatch({
          changes: {
            ...range,
            insert: value,
          },
          selection: {
            anchor:
              mode === 'insert'
                ? head + value.length
                : Math.min(
                    currentDocumentLength,
                    suggestionsContext.current.token.range.from,
                  ) + value.length,
          },
          annotations: stringAnnotation.of('suggestion.apply'),
        });
      },
      [],
    );

    const ariaAttributes = useMemo(() => {
      const { 'aria-label': ariaLabel, 'aria-labelledby': ariaLabelledBy } =
        ariaLabelingProps;

      return {
        ...ariaLabelingProps,
        ...(!ariaLabel &&
          !ariaLabelledBy && { 'aria-label': defaultAriaLabel }),
        'aria-haspopup': 'listbox',
        'aria-controls': `suggestions-${uniqueId}`,
        'aria-expanded': `${overlayState.isOpen}`,
        'aria-activedescendant': `${focusedSuggestion}`,
      };
    }, [
      ariaLabelingProps,
      defaultAriaLabel,
      focusedSuggestion,
      overlayState.isOpen,
      uniqueId,
    ]);

    // Reference of the currently applied value, stored in a ref to avoid constantly
    // reconfiguring the editor.
    const valueRef = useRef(value ?? defaultValue ?? '');
    // Reference of the transaction needed to get from the current state to the next
    // state if the filter field is controlled.
    const transactionRef = useRef<TransactionSpec[] | undefined>();

    /**
     * Effect for configuring the editor.
     * Only called on mount.
     * State variables / stateful functions needed are either stored in refs or updated using codemirror compartments.
     */
    useEffect(() => {
      if (!containerRef.current) {
        return;
      }

      const initialEditorState = EditorState.create({
        doc: value ?? defaultValue ?? '',
        extensions: [
          /**
           * General
           */
          // Enable line wrapping so that overflowing text is wrapped into the next line.
          EditorView.lineWrapping,
          // Enable multiple selections (CMD / ctrl + drag).
          EditorState.allowMultipleSelections.of(true),
          // Enable displaying a placeholder text.
          placeholderCompartment.of(
            placeholderExtension(placeholderProp ?? placeholder),
          ),

          keymap.of([
            ...defaultKeymap.filter(
              ({ key }) => !overrideKeys.includes(key || ''),
            ),
            ...closeBracketsKeymap,
            {
              // NOTE: The shortcut will pbly change.
              key: 'Alt-Space',
              run: (view) => {
                // NOTE: If we ever run into an issue that the overlay state changes, we'd
                // have to store it in a ref to always the most recent overlay state here.
                // So far, everything is working as expected for the suggestions overlay.
                overlayState.open();
                startCompletion(view);
                return true;
              },
            },
            {
              key: 'Shift-Enter',
              run: insertBlankLine,
            },
            {
              key: 'Escape',
              run: () => {
                overlayState.close();
                return false;
              },
            },
          ]),

          /**
           * Linting
           */
          filterFieldLinter,

          /**
           * Filter field language + syntax highlighting.
           *
           * Error highlighting is also done with the highlight extensions, since using an actual
           * linter, potential errors only show up after a short (configurable) delay. As soon as
           * you type something again, the errors disappear and then show up again if the input is
           * still invalid. Using the decoration plugins, we can immediately show errors.
           * The actual linter extension is only used to show tooltips with proper error messages.
           */
          // The extension for parsing the filter field language into a syntax tree.
          filterFieldLanguageExtension,
          // Automatically close brackets.
          closeBrackets(),

          // Enable highlighting using the defined highlighter.
          // This adds the spans and classes used to style the different parts of a filter.
          syntaxHighlighting(filterFieldHighlighter),
          // Add decoration plugins for wrapping filter groups, statements, keys, and values
          // in additional spans for styling. This is not possible using only a highlighter
          // since the highlighter can only wrap nodes that have no more nesting levels.
          FilterErrorDecorationPlugin,
          FilterKeyDecorationPlugin,
          FilterValueDecorationPlugin,
          FilterExistsDecorationPlugin,
          FilterStatementDeleteWidgetPlugin,
          FilterStatementDecorationPlugin,

          /**
           * Suggestions
           */
          suggestionsCompartment.of(
            suggestionsExtension({
              overlayState,
              numberParser: numberParserRef.current,
              onSuggest,
              _onSuggest,
            }),
          ),

          /**
           * Aria attributes
           */
          ariaAttributesCompartment.of(
            EditorView.contentAttributes.of((view) => ariaAttributes),
          ),

          /**
           * Listeners
           */
          // Intercept transactions that change the doc to not instantly apply the changes
          // in a controlled scenario. Instead, the transaction is stored so we can apply
          // it if the consumer actually updates the value.
          EditorState.transactionFilter.of((transaction) => {
            if (transaction.docChanged) {
              setHideDeleteWhileTyping(true);

              let newValue = transaction.newDoc.toString();
              let transactions: TransactionSpec[] = [];

              if (newValue !== valueRef.current) {
                const tree = syntaxTree(transaction.state);

                // Run auto-formatter for any modifications of the document other than deletions.
                // If something is deleted, the auto-formatter has already been executed when the
                // new document was entered.
                if (
                  !transaction.isUserEvent('delete.backward') &&
                  !transaction.isUserEvent('delete.forward')
                ) {
                  [newValue, transactions] = autoFormatLogicalOperators(
                    newValue,
                    tree,
                    transaction.selection?.ranges[
                      transaction.selection?.mainIndex ?? 0
                    ].to ?? 0,
                  );
                }

                const { tree: convertedTree, hasError } = convertLezerTree(
                  tree,
                  numberParserRef.current,
                  transaction.newDoc,
                );
                setHasSyntaxError(hasError);

                // INFO: Workaround for React17, where the onChange may be triggered before
                // all the codemirror transactions are through, potentially leading to an
                // endless loop or codemirror range errors when typing really fast.
                setTimeout(() => {
                  onChange?.(newValue, convertedTree);
                  onInputChange();
                });

                transactionRef.current = [transaction];
                const userEvent = transaction.annotation(Transaction.userEvent);
                transactionRef.current = [
                  {
                    ...transaction,
                    // On Windows / Linux, hitting 'Shift + Delete' results in an undefined selection,
                    // leading to the suggestions callback not being triggered.
                    // Even for an empty value, there should always be a selection.
                    selection: transaction.selection ?? { anchor: 0 },
                    // Annotations are not automatically stored, we need to do that manually
                    // to be able to determine, which action trigger the transaction when applying
                    // the new value in a controlled scenario.
                    annotations: Transaction.userEvent.of(
                      userEvent
                        ? userEvent
                        : transaction.annotation(stringAnnotation) ?? '',
                    ),
                  },
                  ...transactions,
                ];

                if (!isControlled) {
                  valueRef.current = newValue;
                  onInputChange();
                }

                return isControlled ? {} : [transaction, ...transactions];
              }
            }

            return transaction;
          }),
        ],
      });

      const editorView = new EditorView({
        state: initialEditorState,
        parent: containerRef.current,
      });
      editorViewRef.current = editorView;

      const { hasError } = convertLezerTree(
        syntaxTree(editorView.state),
        numberParserRef.current,
        editorView.state.doc,
      );
      setHasSyntaxError(hasError);

      return () => {
        editorView.destroy();
      };
      // Only run for initializing the filter field.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Update configuration compartments that are depending on props when the props change.
    if (placeholderProp !== prevPlaceholderProp) {
      editorViewRef.current?.dispatch({
        effects: placeholderCompartment.reconfigure(
          placeholderExtension(placeholderProp ?? placeholder),
        ),
      });

      setPrevPlaceholderProp(placeholderProp);
    }

    // Re-configure the suggestions extension to use a potentially changed callback.
    if (onSuggest !== prevOnSuggest) {
      editorViewRef.current?.dispatch({
        effects: suggestionsCompartment.reconfigure(
          suggestionsExtension({
            overlayState,
            numberParser: numberParserRef.current,
            onSuggest,
            _onSuggest,
          }),
        ),
      });

      setPrevOnSuggest(() => onSuggest);
    }

    // Dispatch a transaction to update the editor's doc to match the prop
    // value if it changes and the filter field is controlled.
    // Since the value may have been adjusted in the `onChange` callback, we replace the whole document.
    // FIXME: the cursor position jumps in case the value's length changes in the controlled state update.
    if (value !== prevValue && isControlled) {
      setPrevValue(value);
      valueRef.current = value;

      // Wait for any previous codemirror transactions to go through, else it will
      // throw an error that we are trying to update a state that doesn't start
      // from the previous state.
      setTimeout(() => {
        try {
          onInputChange();
          editorViewRef.current?.dispatch({
            changes: {
              from: 0,
              to: editorViewRef.current.state.doc.length,
              insert: value,
            },
            selection:
              transactionRef.current &&
              transactionRef.current[transactionRef.current.length - 1]
                .selection,
          });

          transactionRef.current = undefined;
        } catch (e) {
          // Intentionally left empty.
          // INFO: When typing really fast, it may happen that the selection points outside
          // the current document due to the changes not yet being applied in the codemirror state.
          // Catching those errors, we may lose some keypresses, but at least the filter field does
          // not crash and burn.
        }
      });
    }

    if (
      propDisabled !== prevPropDisabled ||
      propRequired !== prevPropRequired ||
      propId !== prevPropId
    ) {
      setPrevPropDisabled(propDisabled);
      setPrevPropRequired(propRequired);
      setPrevPropId(propId);

      formFieldContextDispatch?.({
        type: FormFieldAction.UPDATE,
        payload: {
          id: propId,
          disabled: propDisabled,
          required: propRequired,
        },
      });
    }

    if (prevOpen !== overlayState.isOpen && overlayState.isOpen === false) {
      // Defer triggering the onSuggest callback one tick, else the filter field is still rendering
      // while the callback may already update the suggestions, which would lead to a runtime error.
      // (Cannot update a component while rendering a different component)
      setTimeout(() => {
        onSuggest?.();
      });
    }

    // Update the currently focused suggestion.
    if (
      prevOpen !== overlayState.isOpen ||
      prevChildren !== children ||
      prevShowLogicalOperatorSuggestions !== showLogicalOperatorSuggestions ||
      prevShowComparisonOperatorSuggestions !==
        showComparisonOperatorSuggestions ||
      prevShowValueSuggestions !== showValueSuggestions
    ) {
      if (overlayState.isOpen) {
        // Set timeout is needed to wait for potentially updated suggestions to render
        // before setting the virtual focus.
        setTimeout(() => {
          // If the currently focused suggestion is still in the document, do nothing.
          if (
            getCurrentSuggestion(
              suggestionsOverlayRef.current,
              focusedSuggestion,
            )
          ) {
            return;
          }

          setFocusedSuggestion(undefined);
        });
      }

      setPrevOpen(overlayState.isOpen);
      setPrevChildren(children);
      setPrevShowLogicalOperatorSuggestions(showLogicalOperatorSuggestions);
      setPrevShowComparisonOperatorSuggestions(
        showComparisonOperatorSuggestions,
      );
      setPrevShowValueSuggestions(showValueSuggestions);
    }

    // Update aria attributes if overlay state or focused suggestion changes.
    if (
      prevFocusedSuggestion !== focusedSuggestion ||
      prevOpen !== overlayState.isOpen
    ) {
      editorViewRef.current?.dispatch({
        effects: ariaAttributesCompartment.reconfigure(
          EditorView.contentAttributes.of(ariaAttributes),
        ),
      });
    }

    const handleClearButton = () => {
      if (!isControlled) {
        valueRef.current = '';
        editorViewRef.current?.dispatch({
          changes: {
            from: 0,
            to: editorViewRef.current.state.doc.length,
            insert: '',
          },
        });
      }

      if (editorViewRef.current) {
        onChange?.('', []);
      }

      onInputChange();
    };

    const autoSuggestionsConfig = useMemo(() => {
      const filterValue = suggestionsContext.current?.currentStatement?.value;
      const cursorPosition = editorViewRef.current?.state.selection.main.head;

      return {
        trailing: cursorPosition === filterValue?.range.to ? ' ' : '',
        showComparisonOperatorSuggestions,
        showLogicalOperatorSuggestions,
        showValueSuggestions,
      };
    }, [
      showComparisonOperatorSuggestions,
      showLogicalOperatorSuggestions,
      showValueSuggestions,
    ]);

    return (
      <FilterFieldContext.Provider
        value={{
          applySuggestion,
          dispatch,
          focusedSuggestion,
          filterFieldId: uniqueId,
          term: suggestionsContext.current?.token.textValue,
          autoSuggestions: autoSuggestions ? autoSuggestionsConfig : {},
        }}
      >
        <Flex
          data-testid={dataTestId}
          gap={4}
          flexDirection="column"
          className={consumerClassName}
          style={consumerStyle}
          onMouseMove={() => {
            setHideDeleteWhileTyping(false);
          }}
          {...containerProps}
        >
          <EditorContainer
            ref={rootRef}
            $size="default"
            $fullHeight={false}
            $hasError={hasError}
            $hideLineNumbers={true}
            {...inputProps}
            className={clsx(filterFieldContainer, props.className, {
              [filterFieldError]: hasError,
              hideDeleteWhileTyping,
            })}
            onBlur={onInputBlur}
            onKeyDown={(event: React.KeyboardEvent) => {
              switch (event.key) {
                case 'Enter': {
                  event.preventDefault();

                  if (event.shiftKey || !editorViewRef.current) {
                    return;
                  }

                  if (!focusedSuggestion || event.ctrlKey || event.metaKey) {
                    validate();

                    const { tree, hasError } = convertLezerTree(
                      syntaxTree(editorViewRef.current.state),
                      numberParserRef.current,
                      editorViewRef.current.state.doc,
                    );
                    onFilter?.({
                      value: valueRef.current,
                      syntaxTree: tree,
                      isValid: hasError,
                    });

                    if (!hasSyntaxError && hiddenInputRef.current?.form) {
                      let inputCount = 0;
                      for (const element of Array.from(
                        hiddenInputRef.current.form.elements,
                      )) {
                        // Check if the filter field is the only visible form control.
                        // Elements included are listed here: https://developer.mozilla.org/en-US/docs/Web/API/HTMLFormElement/elements#value
                        if (
                          !element.hasAttribute('hidden') &&
                          ((element.tagName === 'INPUT' &&
                            element.getAttribute('type') !== 'hidden') ||
                            element.tagName === 'SELECT' ||
                            element.tagName === 'TEXTAREA')
                        ) {
                          inputCount += 1;

                          if (inputCount > 1) {
                            break;
                          }
                        }
                      }

                      if (inputCount === 1) {
                        hiddenInputRef.current?.form?.requestSubmit();
                      }
                    } else {
                      // We have to wait for the form field to set the validity of the form control.
                      // Then reporting the validity triggers the 'invalid' event, which can be captured on the form.
                      setTimeout(() => {
                        hiddenInputRef.current?.form?.reportValidity();
                      });
                    }
                  }

                  if (focusedSuggestion) {
                    state.suggestions.get(focusedSuggestion)?.();
                    return;
                  }
                  break;
                }
              }

              // FIXME: the suggestions overlay may be empty, then we shouldn't handle the keys.
              if (overlayState.isOpen) {
                if (overrideKeys.includes(event.key)) {
                  event.preventDefault();
                  event.stopPropagation();
                }

                switch (event.key) {
                  case 'ArrowUp': {
                    const nextSuggestion = getNextSuggestion(
                      'previous',
                      suggestionsOverlayRef.current,
                      focusedSuggestion,
                    );
                    nextSuggestion &&
                      setFocusedSuggestion(
                        nextSuggestion.dataset.stratoFilterFieldSuggestionId,
                      );
                    break;
                  }
                  case 'ArrowDown': {
                    const nextSuggestion = getNextSuggestion(
                      'next',
                      suggestionsOverlayRef.current,
                      focusedSuggestion,
                    );
                    nextSuggestion &&
                      setFocusedSuggestion(
                        nextSuggestion.dataset.stratoFilterFieldSuggestionId,
                      );
                    break;
                  }
                }
              }
            }}
          >
            <span
              className={filterIconCSS({
                hasError: hasError,
              })}
            >
              {hasError ? (
                <CriticalIcon data-testid="strato-filter-field-error-icon" />
              ) : (
                <FilterIcon />
              )}
            </span>
            <div ref={containerRef} />
            {valueRef.current && (
              <SharedInputPropsContext.Provider value={{}}>
                <span className={clearButton}>
                  <Button
                    size="condensed"
                    onClick={handleClearButton}
                    aria-label={intl.formatMessage({
                      defaultMessage: 'Clear filter',
                      id: 'mS6CPzO+pMJLetSA',
                      description:
                        'Aria label used for the clear button inside the filter field.',
                    })}
                    color={hasError ? 'critical' : 'neutral'}
                    style={{ borderRadius: Borders.Radius.Field.Subdued }}
                  >
                    <Button.Prefix>
                      <XmarkIcon></XmarkIcon>
                    </Button.Prefix>
                  </Button>
                </span>
              </SharedInputPropsContext.Provider>
            )}
          </EditorContainer>
          {
            <SuggestionsOverlay
              ref={overlayRef}
              isOpen={overlayState.isOpen}
              overlayProps={{ style: overlayStyles }}
            >
              {children}
            </SuggestionsOverlay>
          }
          <Hint hasError={hasError} disabled={disabled} {...hintProps}>
            {hint}
          </Hint>
          <VisuallyHidden>
            <input
              ref={hiddenInputRef}
              name={name}
              value={valueRef.current}
              required={required}
              disabled={disabled}
              id={propId ?? controlId}
              onFocus={() => {
                // The focus should move to the FilterField when clicking on
                // the label (when using it in a FormField)
                editorViewRef.current?.focus();
              }}
              onChange={() => {
                /** noop */
              }}
              onInvalid={(event) => {
                event.preventDefault();
                event.currentTarget.focus();
                onInputBlur();
              }}
            />
          </VisuallyHidden>
        </Flex>
      </FilterFieldContext.Provider>
    );
  },
);

(_FilterField as typeof FilterField & { displayName: string }).displayName =
  'FilterField';

/**
 * The `FilterField` component is a text-based input component that allows users
 * to enter filters using an intuitive and easily understandable syntax.
 * Since the input is text-based, users can always enter anything they want.
 * To provide guidance to the user, we recommend always using the `FilterField`
 * in combination with suggestions.
 */
export const FilterField = Object.assign(_FilterField, {
  Suggestions,
  Suggestion,
  SuggestionGroup,
  SuggestionGroupLabel,
  SuggestionDetails,
});
